recipes.command:
pkg install -y clang && mkdir -p apps/c_project && cd apps/c_project && cat << 'CEOF' > main.c
#include <stdio.h>
int main() {
    printf("VERY SYSTEMS - Executavel C Nativo\n");
    return 0;
}
CEOF
clang main.c -o app && ./app

pkg install -y rust && mkdir -p apps/rust_project && cd apps/rust_project && cat << 'RSTEOF' > main.rs
fn main() {
    println!("VERY SYSTEMS - Rust compilado com sucesso!");
}
RSTEOF
rustc main.rs && ./main
